<?php
if(!$PCC->tableExists('rp_item_definitions')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-cubes"></i><strong>Item Definitions indisponibles</strong><span>rp_item_definitions n’existe pas.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$category=strtoupper(trim((string)($_GET['category']??'')));$where=array('1=1');$types='';$params=array();if($q!==''){$like='%'.mb_substr($q,0,64).'%';$where[]='(d.name LIKE ? OR d.code LIKE ? OR d.description LIKE ?)';$types.='sss';$params=array($like,$like,$like);}if($category!==''&&preg_match('/^[A-Z_]{1,32}$/',$category)){$where[]='UPPER(d.category)=?';$types.='s';$params[]=$category;}$inv=$PCC->tableExists('rp_inventory_items');$join=$inv?' LEFT JOIN rp_inventory_items i ON i.item_definition_id=d.id':'';$circulation=$inv?',COALESCE(SUM(i.quantity),0) circulation,COUNT(DISTINCT i.owner_user_id) owners':',0 circulation,0 owners';$rows=$DB->PreparedAll('SELECT d.*'.$circulation.' FROM rp_item_definitions d'.$join.' WHERE '.implode(' AND ',$where).' GROUP BY d.id ORDER BY d.category,d.name LIMIT 500',$types,$params);$cats=$DB->PreparedAll('SELECT DISTINCT category FROM rp_item_definitions ORDER BY category');
?>
<section class="pcc-alert info"><i class="fas fa-shield-alt"></i><div><strong>Suppression destructive désactivée</strong><p>La circulation est calculée en temps réel. Une définition déjà possédée par des joueurs ne doit pas être supprimée brutalement ; le futur workflow de gestion privilégiera désactivation/archivage après audit de l’impact.</p></div></section>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="items"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Nom, code ou description…"></div><select name="category" class="pcc-select-compact"><option value="">Toutes catégories</option><?php foreach($cats as $c):?><option value="<?php echo $h($c['category']);?>" <?php echo $category===strtoupper($c['category'])?'selected':'';?>><?php echo $h($c['category']);?></option><?php endforeach;?></select><button class="pcc-button secondary">Filtrer</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> définition(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>ID</th><th>Objet</th><th>Code</th><th>Catégorie</th><th>Poids</th><th>Stack max</th><th>Utilisable</th><th>Échangeable</th><th>Effet</th><th>Circulation</th><th>Propriétaires</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?php echo (int)$r['id'];?></td><td><strong><?php echo $h($r['name']);?></strong><small class="pcc-subline"><?php echo $h($r['description']);?></small></td><td><code><?php echo $h($r['code']);?></code></td><td><?php echo $h($r['category']);?></td><td><?php echo $h(number_format((float)$r['weight'],3,',',' '));?> kg</td><td><?php echo (int)$r['max_stack'];?></td><td><span class="pcc-badge <?php echo !empty($r['usable'])?'success':'';?>"><?php echo !empty($r['usable'])?'OUI':'NON';?></span></td><td><span class="pcc-badge <?php echo !empty($r['tradeable'])?'success':'';?>"><?php echo !empty($r['tradeable'])?'OUI':'NON';?></span></td><td><code><?php echo $h($r['effect_type']);?></code><?php if((int)$r['effect_value']!==0):?> <?php echo (int)$r['effect_value'];?><?php endif;?></td><td><strong><?php echo $number($r['circulation']);?></strong></td><td><?php echo $number($r['owners']);?></td></tr><?php endforeach;?></tbody></table></div></section>
